<template>
  <div class="service-form">
    <template v-if="mode==='basic'">
      <section class="service-section"><div class="service-section-heading"><span class="service-section-icon"><el-icon><Connection/></el-icon></span><div><h3>服务类型</h3><p>选择访问服务的方式</p></div></div>
        <div class="service-type-grid"><button v-for="item in serviceTypes" :key="item.value" type="button" class="service-type-option" :class="{active:serviceType===item.value}" :disabled="disabled" :aria-pressed="serviceType===item.value" @click="spec.type=item.value"><el-icon><component :is="item.icon"/></el-icon><strong>{{item.value}}</strong><span>{{item.label}}</span><el-icon v-if="serviceType===item.value" class="service-type-check"><CircleCheckFilled/></el-icon></button></div>
        <el-form-item v-if="serviceType==='ExternalName'" label="外部域名" required><el-input v-model="spec.externalName" :disabled="disabled" aria-label="外部域名" placeholder="例如 api.example.com"/></el-form-item>
        <div v-else class="service-address-line"><span>集群 IP</span><el-tag effect="plain" type="info">{{spec.clusterIP||'自动分配'}}</el-tag><el-tag v-for="family in spec.ipFamilies||[]" :key="family" type="info" effect="plain">{{family}}</el-tag><el-tag v-if="spec.clusterIP==='None'" effect="plain">Headless</el-tag></div>
      </section>
      <section v-if="serviceType!=='ExternalName'" class="service-section"><div class="service-section-heading"><span class="service-section-icon green"><el-icon><Aim/></el-icon></span><div><h3>容器组选择器</h3><p>匹配提供服务的 Pod 标签</p></div></div><KeyValueFields v-model="spec.selector" label="选择器" add-label="添加选择器" :disabled="disabled" @change="emit('change')" @validity="value=>emit('validity',value)"/></section>
      <section class="service-section"><div class="service-section-heading"><span class="service-section-icon"><el-icon><Operation/></el-icon></span><div><h3>流量设置</h3><p>会话保持与流量分配</p></div></div><div class="service-option-grid"><el-form-item label="会话保持"><el-select :model-value="spec.sessionAffinity||'None'" :disabled="disabled" aria-label="会话保持" @update:model-value="value=>spec.sessionAffinity=value"><el-option label="不保持（None）" value="None"/><el-option label="按客户端 IP（ClientIP）" value="ClientIP"/></el-select></el-form-item><el-form-item v-if="serviceType!=='ExternalName'" label="集群内流量"><el-select :model-value="spec.internalTrafficPolicy||'Cluster'" :disabled="disabled" aria-label="集群内流量" @update:model-value="value=>spec.internalTrafficPolicy=value"><el-option label="全部节点（Cluster）" value="Cluster"/><el-option label="本地节点（Local）" value="Local"/></el-select></el-form-item><el-form-item v-if="serviceType!=='ExternalName'&&(['NodePort','LoadBalancer'].includes(serviceType)||spec.externalIPs?.length)" label="外部流量"><el-select :model-value="spec.externalTrafficPolicy||'Cluster'" :disabled="disabled" aria-label="外部流量" @update:model-value="value=>spec.externalTrafficPolicy=value"><el-option label="全部节点（Cluster）" value="Cluster"/><el-option label="本地节点（Local）" value="Local"/></el-select></el-form-item><el-form-item label="未就绪地址"><el-switch :model-value="!!spec.publishNotReadyAddresses" :disabled="disabled" aria-label="发布未就绪地址" @update:model-value="value=>spec.publishNotReadyAddresses=value"/></el-form-item></div></section>
    </template>
    <template v-else>
      <div class="service-ports-heading"><div><h3><el-icon><Switch/></el-icon>服务端口 <el-tag size="small" type="info">{{ports.length}}</el-tag></h3><p>服务端口与容器目标端口的映射</p></div><el-button :icon="Plus" :disabled="disabled" @click="addPort">添加端口</el-button></div>
      <div :class="{'service-port-tabs':mode==='tabs'}">
        <aside v-if="mode==='tabs'" class="service-port-nav"><button v-for="(port,index) in ports" :key="index" type="button" :class="{active:active===index}" @click="active=index"><el-icon><Connection/></el-icon><span>{{port.name||`端口 ${index+1}`}}<small>{{port.port||'—'}} / {{port.protocol||'TCP'}}</small></span></button></aside>
        <div class="service-port-list"><section v-for="(port,index) in ports" v-show="mode!=='tabs'||active===index" :key="index" class="service-port-card"><div class="port-card-heading"><strong><span class="port-number">{{index+1}}</span>{{port.name||'新端口'}}</strong><el-tag size="small" effect="plain">{{port.protocol||'TCP'}}</el-tag><el-button :disabled="disabled" text type="danger" :icon="Delete" :aria-label="`删除服务端口 ${index+1}`" @click="removePort(index)"/></div>
          <div class="service-port-controls"><el-form-item label="端口名称"><el-input v-model="port.name" :disabled="disabled" :aria-label="`服务端口名称 ${index+1}`" placeholder="例如 http"/></el-form-item><el-form-item label="协议"><el-select :model-value="port.protocol||'TCP'" :disabled="disabled" :aria-label="`服务端口协议 ${index+1}`" @update:model-value="value=>port.protocol=value"><el-option v-for="value in ['TCP','UDP','SCTP']" :key="value" :label="value" :value="value"/></el-select></el-form-item><el-form-item label="服务端口" required><el-input-number v-model="port.port" :min="1" :max="65535" :disabled="disabled" :aria-label="`服务端口号 ${index+1}`"/></el-form-item><div class="port-direction"><el-icon><Right/></el-icon></div><el-form-item label="目标端口"><el-input :model-value="port.targetPort??''" :disabled="disabled" :aria-label="`服务目标端口 ${index+1}`" placeholder="端口号 / 名称" @update:model-value="value=>setTargetPort(port,value)"/></el-form-item><el-form-item v-if="['NodePort','LoadBalancer'].includes(serviceType)" label="节点端口"><el-input :model-value="port.nodePort??''" :disabled="disabled" :aria-label="`服务节点端口 ${index+1}`" placeholder="自动分配" @update:model-value="value=>setNodePort(port,value)"/></el-form-item></div>
          <div class="port-route-preview"><el-tag effect="plain">{{modelValue.metadata.name||'服务'}} : {{port.port||'—'}}</el-tag><el-icon><Right/></el-icon><el-tag type="success" effect="plain">Pod : {{port.targetPort||port.port||'—'}}</el-tag><span v-if="port.nodePort">节点 {{port.nodePort}}</span></div>
        </section><el-empty v-if="!ports.length" description="还没有服务端口" :image-size="72"><el-button :disabled="disabled" type="primary" @click="addPort">添加第一个端口</el-button></el-empty></div>
      </div>
    </template>
  </div>
</template>
<script setup>
import {computed,ref} from 'vue'
import {Connection,Aim,Operation,Switch,Plus,Delete,Right,CircleCheckFilled} from '@element-plus/icons-vue'
import KeyValueFields from './KeyValueFields.vue'
const props=defineProps({modelValue:Object,mode:{type:String,default:'basic'},disabled:Boolean})
const emit=defineEmits(['change','validity'])
const spec=computed(()=>props.modelValue.spec),ports=computed(()=>spec.value.ports||[]),serviceType=computed(()=>spec.value.type||'ClusterIP'),active=ref(0)
const serviceTypes=[{value:'ClusterIP',label:'仅集群内部访问',icon:'Connection'},{value:'NodePort',label:'通过节点端口访问',icon:'Share'},{value:'LoadBalancer',label:'外部负载均衡',icon:'SetUp'},{value:'ExternalName',label:'映射外部域名',icon:'Link'}]
function addPort(){spec.value.ports||=[];let n=spec.value.ports.length+1;while(ports.value.some(port=>port.name===`port-${n}`))n++;spec.value.ports.push({name:`port-${n}`,port:80,targetPort:80,protocol:'TCP'});active.value=ports.value.length-1}
function removePort(index){spec.value.ports.splice(index,1);active.value=Math.min(active.value,Math.max(0,ports.value.length-1))}
function setTargetPort(port,value){if(value==='')delete port.targetPort;else port.targetPort=/^\d+$/.test(value)?Number(value):value}
function setNodePort(port,value){if(value==='')delete port.nodePort;else port.nodePort=Number(value)}
</script>
<style scoped>
.service-form{min-width:0}.service-section{padding:24px 0;border-top:1px solid var(--kp-border);margin-top:14px}.service-section-heading{display:flex;align-items:center;gap:12px;margin-bottom:20px}.service-section-heading h3,.service-ports-heading h3{font-size:15px;margin:0;display:flex;align-items:center;gap:9px}.service-section-heading p,.service-ports-heading p{font-size:12px;color:var(--kp-muted);margin:5px 0 0}.service-section-icon{width:36px;height:36px;display:grid;place-items:center;background:var(--kp-side-active);color:var(--kp-brand);border-radius:10px;font-size:19px}.service-section-icon.green{background:#ecfdf5;color:#059669}.service-type-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:20px}.service-type-option{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:8px;padding:18px;border:1px solid var(--kp-border);border-radius:10px;background:var(--kp-surface);font:inherit;cursor:pointer;text-align:left;color:var(--kp-text)}.service-type-option>.el-icon{font-size:22px;color:var(--kp-muted)}.service-type-option>strong{font-size:14px}.service-type-option>span{font-size:12px;color:var(--kp-muted)}.service-type-option.active{border-color:var(--kp-brand);background:var(--kp-side-active);box-shadow:0 0 0 1px var(--kp-brand) inset}.service-type-option.active>.el-icon{color:var(--kp-brand)}.service-type-option>.service-type-check{position:absolute;right:12px;top:12px;font-size:16px}.service-address-line{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:var(--kp-surface-2);padding:14px;border-radius:8px;font-size:13px;color:var(--kp-muted)}.service-option-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px}.service-ports-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:22px}.service-port-tabs{display:grid;grid-template-columns:185px minmax(0,1fr);gap:22px}.service-port-nav{display:flex;flex-direction:column;gap:6px;border-right:1px solid var(--kp-border);padding-right:16px}.service-port-nav>button{display:flex;align-items:center;gap:10px;border:0;border-radius:8px;padding:14px;background:transparent;font:inherit;cursor:pointer;text-align:left;color:var(--kp-text)}.service-port-nav>button.active{color:var(--kp-brand);background:var(--kp-side-active)}.service-port-nav small{display:block;color:var(--kp-muted);margin-top:5px}.service-port-list{min-width:0}.service-port-card{border:1px solid var(--kp-border);border-radius:13px;margin-bottom:16px;overflow:hidden}.port-card-heading{display:flex;align-items:center;gap:12px;padding:13px 18px;background:var(--kp-surface-2);border-bottom:1px solid var(--kp-border)}.port-card-heading>strong{display:flex;gap:10px;align-items:center;flex:1;font-size:14px}.port-number{display:inline-grid;place-items:center;width:24px;height:24px;border-radius:7px;background:var(--kp-side-active);color:var(--kp-brand);font-size:12px}.service-port-controls{display:grid;grid-template-columns:minmax(120px,1.1fr) 110px minmax(120px,1fr) 24px minmax(130px,1fr) minmax(120px,1fr);gap:14px;align-items:end;padding:20px}.service-port-controls :deep(.el-form-item){display:flex;flex-direction:column;align-items:stretch;margin:0!important;min-width:0}.service-port-controls :deep(.el-form-item__label){justify-content:flex-start;text-align:left;width:auto!important;margin-bottom:8px;line-height:20px;height:auto}.service-port-controls :deep(.el-form-item__content){margin-left:0!important;min-width:0}.service-port-controls :deep(.el-input-number){width:100%}.service-port-controls :deep(.el-input),.service-port-controls :deep(.el-select){width:100%}.port-direction{display:grid;place-items:center;height:34px;color:var(--kp-muted)}.port-route-preview{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 20px;border-top:1px dashed var(--kp-border);font-size:12px;color:var(--kp-muted)}
@media(max-width:1150px){.service-port-controls{grid-template-columns:repeat(3,minmax(0,1fr))}.port-direction{display:none}.service-type-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:700px){.service-port-tabs{grid-template-columns:minmax(0,1fr)}.service-port-nav{flex-direction:row;flex-wrap:wrap;border-right:0;border-bottom:1px solid var(--kp-border);padding-bottom:12px}.service-port-controls{grid-template-columns:repeat(2,minmax(0,1fr));padding:14px;gap:12px}.service-option-grid{grid-template-columns:minmax(0,1fr)}.service-type-option{padding:12px}.service-type-option>strong{font-size:12px}.service-ports-heading{align-items:flex-start}.service-section{padding-top:20px}}
</style>
